sys_script_fix.script:
function getHrs(gdt) {
    var gt = gdt.getTime(); // extract time
    var timeStr = gt.getByFormat('HH:mm:ss'); // 24 hour format
    var split = timeStr.split(":");
    var hour = split[0]; //splitting the hours // today hours
    return hour;
}

//gs.info('UTC ' + gs.nowNoTZ());
//Extract today hours
