gs.info("UTC "+ today);
today.addSeconds(28800); //convert to HKT
gs.info("HKT "+ today);
var todayHrs = parseInt(getHrs(today));
var todayaddTwoHrs = todayHrs + 2; //adding two hours to check if it corssed 5PM HKT


